"""Semantic registration pages; behavior and prices are supplied by the API."""
def field(name,label,kind='text',autocomplete='',required=True,extra=''):
 return f'<div class="join-field"><label for="{name}">{label}{" *" if required else ""}</label><input id="{name}" name="{name}" type="{kind}" autocomplete="{autocomplete}" {"required" if required else ""} aria-describedby="error-{name}" {extra}><span class="field-error" id="error-{name}"></span></div>'

def build_membership(page,head):
 body='''<section class="join-intro" data-viewport-hero><div class="wrap"><div><p class="eyebrow">17/7 Performance Gym · Rheinbach</p><h1>Dein Gym.<br><span>Dein nächster Schritt.</span></h1><p>Dein Training verdient einen festen Platz. Wähle deine Mitgliedschaft – Schritt für Schritt zu deinen Vertragsunterlagen.</p><a class="hero-scroll join-start" href="#anmeldung">Tarif wählen & starten <span aria-hidden="true">↓</span></a><p class="join-intro-note" id="join-intro-note">Vier Schritte · Kein Benutzerkonto nötig</p></div><div class="join-promises"><span>01 <strong>Passenden Tarif wählen</strong></span><span>02 <strong>Angaben in Ruhe prüfen</strong></span><span>03 <strong>Vertrag als PDF erhalten</strong></span></div></div></section>
<section class="join-area" id="anmeldung"><div class="wrap"><div class="preview-notice" id="join-mode" role="status">Anmeldung wird vorbereitet …</div><noscript><p class="preview-notice">Für die digitale Vorschau benötigst du JavaScript. Unser Team hilft dir auch unter <a href="tel:+4922269111999">02226 91 11 999</a>.</p></noscript><div class="join-connection" id="join-connection" hidden><button class="btn secondary" type="button" id="join-retry">Erneut verbinden ↻</button><a href="tel:+4922269111999">Oder persönlich: 02226 91 11 999</a></div><div class="join-layout"><div class="join-main"><ol class="join-progress" aria-label="Anmeldeschritte"><li aria-current="step"><button type="button" data-step-link="0"><span>1</span>Tarif</button></li><li><button type="button" data-step-link="1" disabled><span>2</span>Deine Daten</button></li><li><button type="button" data-step-link="2" disabled><span>3</span>Zahlung</button></li><li><button type="button" data-step-link="3" disabled><span>4</span>Prüfen</button></li></ol>
<form id="membership-form" novalidate><div id="join-error" class="join-error" role="alert" hidden></div><div class="honeypot" aria-hidden="true"><label>Website<input name="website" tabindex="-1" autocomplete="off"></label></div>
<section class="join-step" data-step="0"><p class="eyebrow">01 / Dein Rhythmus</p><h2>Was passt zu dir?</h2><p class="step-intro">Regelmäßig trainieren oder flexibel bleiben. Du entscheidest.</p><fieldset class="join-plans"><legend class="sr-only">Mitgliedschaft wählen</legend><label class="join-plan"><input type="radio" name="plan" value="standard" checked><span class="join-plan-body"><span class="plan-kicker">Für deine Routine</span><strong>Standard</strong><span class="join-price">26,99 € <small>/ Monat</small></span><span>12 Monate Erstlaufzeit</span><span class="plan-check">10 € weniger pro Monat als Starter</span></span></label><label class="join-plan"><input type="radio" name="plan" value="starter"><span class="join-plan-body"><span class="plan-kicker">Für deine Flexibilität</span><strong>Starter</strong><span class="join-price">36,99 € <small>/ Monat</small></span><span>1 Monat Erstlaufzeit</span><span class="plan-check">Monatlich kündbar</span></span></label></fieldset><p class="join-fine">Jeweils zuzüglich einmalig 19,99 € für das E-Band. Keine Aufnahmegebühr.</p>'''+field('start_date','Wann möchtest du starten?','date')+'''<div class="join-benefits"><span>✓ Kraft, Cardio & Functional Training</span><span>✓ Kostenfrei parken & WLAN nutzen</span></div><details class="join-help"><summary>Unter 18, Firma, Verein oder Sicherheitskräfte?</summary><p>Diese Mitgliedschaften stimmen wir wegen ihrer besonderen Voraussetzungen persönlich mit dir ab. <a href="/preise-aktionen/">Tarife und Voraussetzungen ansehen</a> oder <a href="/contact/">das Team kontaktieren</a>.</p></details></section>
<section class="join-step" data-step="1" hidden><p class="eyebrow">02 / Schön, dich kennenzulernen</p><h2>Wer trainiert bei uns?</h2><p class="step-intro">Diese Angaben übernehmen wir in deine Vertragsunterlagen. Ein Benutzerkonto brauchst du nicht.</p><div class="join-fields">'''+field('first_name','Vorname',autocomplete='given-name',extra='maxlength="80"')+field('last_name','Nachname',autocomplete='family-name',extra='maxlength="80"')+field('birthdate','Geburtsdatum','date','bday')+field('email','E-Mail für deinen PDF-Vertrag','email','email',extra='maxlength="150" inputmode="email" autocapitalize="none" spellcheck="false"')+'''</div>'''+field('street','Straße und Hausnummer',autocomplete='street-address',extra='maxlength="180"')+'''<div class="join-fields">'''+field('postcode','Postleitzahl',autocomplete='postal-code',extra='maxlength="16"')+field('city','Ort',autocomplete='address-level2',extra='maxlength="100"')+field('country','Land',autocomplete='country-name',extra='value="Deutschland" maxlength="80"')+field('phone','Telefon (optional)','tel','tel',False,extra='maxlength="60"')+'''</div><p class="join-fine">Die Online-Anmeldung ist ab 18 möglich. Deine Daten werden für deine Mitgliedschaft verwendet. <a href="/datenschutzerklaerung/#mitgliedschaft">Datenschutzhinweise</a></p></section>
<section class="join-step" data-step="2" hidden><p class="eyebrow">03 / Monatlich. Unkompliziert.</p><h2>So bezahlst du.</h2><p class="step-intro">Dein Mitgliedsbeitrag wird per SEPA-Lastschrift bezahlt. Es findet hier keine Kartenzahlung statt.</p><div class="payment-method"><span class="payment-icon" aria-hidden="true">↗</span><div><strong>SEPA-Lastschrift</strong><span>Monatliche Zahlung vom angegebenen Konto</span></div><span class="method-check" aria-hidden="true">✓</span></div>'''+field('account_holder','Kontoinhaber',autocomplete='section-payment name',extra='maxlength="150"')+field('iban','IBAN',autocomplete='off',extra='spellcheck="false" autocapitalize="characters" maxlength="42" placeholder="DE00 0000 0000 0000 0000 00"')+'''<p class="join-fine" id="iban-hint">Bitte verwende in der Vorschau ausschließlich Testdaten.</p><details class="join-help"><summary>SEPA-Mandat und Abbuchung</summary><p id="sepa-text"></p><p><strong>Gläubiger:</strong> 17/7 performance-gym Fitness GmbH Rheinbach<br><strong>Gläubiger-ID:</strong> <span id="creditor-id"></span></p><p id="billing-notice"></p></details><label class="join-consent"><input type="checkbox" name="sepa_consent" id="sepa_consent"><span id="sepa-label">Ich bestätige das Testmandat für diese Vorschau.</span></label><span class="field-error" id="error-sepa_consent"></span></section>
<section class="join-step" data-step="3" hidden><p class="eyebrow">04 / Alles im Blick</p><h2>Passt alles für dich?</h2><p class="step-intro">Prüfe deine Angaben und lade deine Vertragsvorschau herunter. Du kannst jeden Schritt noch bearbeiten.</p><div id="join-review"></div><button type="button" class="btn secondary" id="preview-contract">Vertragsvorschau als PDF ↓</button><div id="legal-documents" class="join-documents"></div><label class="join-consent"><input type="checkbox" name="terms_consent" id="terms_consent"><span id="terms-label">Ich bestätige, dass dies eine unverbindliche Testanmeldung ist.</span></label><span class="field-error" id="error-terms_consent"></span><div id="early-start-box"><label class="join-consent"><input type="checkbox" name="early_start_consent" id="early_start_consent"><span id="early-start-text"></span></label><span class="field-error" id="error-early_start_consent"></span></div><div class="final-price" id="final-price"></div><p class="join-fine" id="final-notice"></p></section>
<div class="join-controls"><button type="button" class="join-back" id="join-back" hidden>← Zurück</button><button type="button" class="btn" id="join-next" disabled>Weiter zu deinen Daten <span aria-hidden="true">→</span></button><button type="submit" class="btn" id="join-submit" hidden>Anmeldung testen</button></div><p class="join-save-note">Du prüfst alles, bevor du abschließt.</p></form><section id="join-success" class="join-success" hidden tabindex="-1"><span class="success-symbol" aria-hidden="true">✓</span><p class="eyebrow">Dein nächster Schritt</p><h2 id="success-title"></h2><p id="success-message"></p><div class="success-reference">Vorgangsnummer <strong id="success-id"></strong></div><a id="success-pdf" class="btn" href="#">PDF herunterladen ↓</a><div class="success-next"><h3>So geht es weiter.</h3><p id="success-next-text"></p><a class="text-link" href="/contact/">Kontakt & Anfahrt →</a></div></section></div>
<aside class="join-summary" aria-label="Deine Kostenübersicht"><p class="eyebrow">Deine Mitgliedschaft</p><h2 id="summary-plan">Standard</h2><p class="summary-price"><strong id="summary-price">26,99 €</strong><span>pro Monat</span></p><details class="summary-breakdown" id="summary-breakdown" open><summary>Kosten & Laufzeit <span aria-hidden="true">+</span></summary><dl><div><dt>Erstlaufzeit</dt><dd id="summary-term">12 Monate</dd></div><div><dt>E-Band, einmalig</dt><dd>19,99 €</dd></div><div><dt>Aufnahmegebühr</dt><dd>0,00 €</dd></div><div><dt>Gewünschter Start</dt><dd id="summary-start">–</dd></div></dl><div class="summary-total"><span>Mindestbetrag der Erstlaufzeit</span><strong id="summary-total">343,87 €</strong></div><p class="join-fine" id="summary-calculation">12 × 26,99 € + 19,99 € E-Band</p></details><p class="summary-personal">Dein Vertrag digital.<br>Dein Team persönlich.</p><a href="tel:+4922269111999" class="summary-phone">Fragen? 02226 91 11 999</a></aside></div></div></section>'''
 page('/mitglied-werden/','Mitglied werden | Performance Gym Rheinbach','Vergleiche Standard und Starter im Performance Gym Rheinbach. Teste die digitale Anmeldung mit klarer Kostenübersicht und Vertragsvorschau als PDF.',body,mobile=False)
 for kind,title,label,button in [('cancellation','Verträge hier kündigen','Kündigung','Jetzt kündigen'),('withdrawal','Vertrag widerrufen','Widerruf','Widerruf bestätigen')]:
  route='/kuendigen/' if kind=='cancellation' else '/widerrufen/'
  extra='''<div class="join-field"><label for="termination">Art der Kündigung</label><select id="termination" name="termination"><option value="ordinary">Ordentliche Kündigung</option><option value="extraordinary">Außerordentliche Kündigung</option></select></div>'''+field('end_date','Gewünschtes Ende (optional)','date',required=False)+'''<p class="join-fine">Ohne Datum: zum nächstmöglichen Zeitpunkt.</p><div class="join-field"><label for="reason">Grund (bei außerordentlicher Kündigung erforderlich)</label><textarea name="reason" id="reason" rows="3" maxlength="2000" aria-describedby="error-reason"></textarea><span class="field-error" id="error-reason"></span></div>''' if kind=='cancellation' else ''
  content=head(title,'Hier kannst du deine Erklärung ohne Anmeldung und ohne Benutzerkonto abgeben. Du erhältst eine Eingangsbestätigung als PDF und per E-Mail.','Deine Mitgliedschaft',crumb=label)+'''<section class="section"><div class="wrap service-wrap"><div class="preview-notice" id="join-mode" role="status">Verbindung wird hergestellt …</div><noscript><p class="preview-notice">Für die digitale Vorschau benötigst du JavaScript. Unser Team hilft dir auch unter <a href="tel:+4922269111999">02226 91 11 999</a>.</p></noscript><div class="join-connection" id="join-connection" hidden><button class="btn secondary" type="button" id="join-retry">Erneut verbinden ↻</button><a href="tel:+4922269111999">Oder persönlich: 02226 91 11 999</a></div><form id="service-form" class="service-form" novalidate>'''+f'<input type="hidden" name="kind" value="{kind}">'+field('name','Vor- und Nachname',autocomplete='name')+field('email','E-Mail für die Bestätigung','email','email')+field('contract','Mitgliedsnummer oder andere eindeutige Vertragsangabe')+extra+f'''<div class="join-error" id="join-error" hidden role="alert"></div><p>Mit dem folgenden Button bestätigst du deine {label.lower()} für den angegebenen Vertrag.</p><button class="btn" type="submit" id="service-submit" disabled>{button}</button></form><section class="join-success" id="service-success" hidden tabindex="-1"><span class="success-symbol">✓</span><h2>Deine Erklärung ist erfasst.</h2><p id="service-message"></p><p id="service-reference"></p><a class="btn" id="service-pdf" href="#">Bestätigung als PDF ↓</a></section></div></section>'''
  page(route,title+' | Performance Gym Rheinbach','Erklärung zur '+label+' deiner Mitgliedschaft online abgeben und eine Eingangsbestätigung erhalten.',content,mobile=False)
